CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS app_state (singleton boolean PRIMARY KEY DEFAULT true CHECK (singleton), payload jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id text PRIMARY KEY, username text NOT NULL, username_normalized text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL CHECK (role IN ('admin','staff','customer')), email text, phone text, verified_at timestamptz, active boolean NOT NULL DEFAULT true, profile jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS auth_sessions (id uuid PRIMARY KEY, family_id uuid NOT NULL, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, access_token_hash text NOT NULL UNIQUE, refresh_token_hash text NOT NULL UNIQUE, access_expires_at timestamptz NOT NULL, refresh_expires_at timestamptz NOT NULL, revoked_at timestamptz, replaced_by uuid, ip_address text, user_agent text, created_at timestamptz NOT NULL DEFAULT now(), last_used_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS auth_sessions_user_idx ON auth_sessions(user_id);
CREATE INDEX IF NOT EXISTS auth_sessions_family_idx ON auth_sessions(family_id);
CREATE TABLE IF NOT EXISTS one_time_tokens (id uuid PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, purpose text NOT NULL CHECK (purpose IN ('password_reset','account_verification')), token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, used_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS login_limits (key_hash text PRIMARY KEY, attempts integer NOT NULL DEFAULT 0, window_started_at timestamptz NOT NULL DEFAULT now(), blocked_until timestamptz);
CREATE TABLE IF NOT EXISTS audit_logs (id uuid PRIMARY KEY, user_id text, event text NOT NULL, entity_type text, entity_id text, ip_address text, user_agent text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_logs_created_idx ON audit_logs(created_at DESC);
CREATE INDEX IF NOT EXISTS audit_logs_user_idx ON audit_logs(user_id, created_at DESC);
CREATE TABLE IF NOT EXISTS notification_outbox (id uuid PRIMARY KEY, channel text NOT NULL CHECK (channel IN ('email','sms')), destination text NOT NULL, template text NOT NULL, payload jsonb NOT NULL, delivered_at timestamptz, attempts integer NOT NULL DEFAULT 0, last_error text, created_at timestamptz NOT NULL DEFAULT now());
